const fs = require('node:fs');
const cp = require('node:child_process');
const crypto = require('node:crypto');
const electron = require('../apps/desktop/node_modules/electron');
const evidencePath = 'wiki-project/raw/b-aw08-revalidation.json';
const sha = value => crypto.createHash('sha256').update(value).digest('hex');
const git = (...args) => cp.execFileSync('git', args, { encoding: 'utf8' }).trim();
const [label, mode, ...args] = process.argv.slice(2);
const record = fs.existsSync(evidencePath) ? JSON.parse(fs.readFileSync(evidencePath, 'utf8')) : {
  status: 'partial', taskBase: git('rev-parse', 'HEAD'), branch: git('branch', '--show-current'),
  environment: { platform: process.platform, arch: process.arch, hostNode: process.version, pnpm: '10.13.1', electron: '44.9.2', macOSVerified: false },
  dependencies: { cEvidence: '20891fb8e8af8f05d68016dbc514c17cdf481fec', aFixed: '92255261e818e6fde0687deee5544755cf9af469', bExistingFix: '330bff76615147ea9c2729cb144a18873a5251d0', aImportedIntoB: false },
  checks: [],
};
function run(executable, argv, expectedExitCode = 0) {
  const startedAt = new Date().toISOString();
  const env = { ...process.env, ELECTRON_RUN_AS_NODE: '1', TEMP: process.cwd() + '/.runtime/test-temp', TMP: process.cwd() + '/.runtime/test-temp' };
  env.GIT_CEILING_DIRECTORIES = env.TEMP;
  const inheritedPath = env.Path ?? env.PATH ?? '';
  for (const key of Object.keys(env)) if (key.toLowerCase() === 'path') delete env[key];
  env.Path = require('node:path').dirname(process.execPath) + ';C:/Users/陈宇柠/AppData/Local/pnpm/bin;' + inheritedPath;
  const result = cp.spawnSync(executable, argv, { encoding: 'utf8', env, maxBuffer: 16 * 1024 * 1024 });
  const output = (result.stdout ?? '') + (result.stderr ?? '');
  record.checks.push({ name: label, executable, argv, startedAt, finishedAt: new Date().toISOString(), exit_code: result.status, expectedExitCode, expectationMet: result.status === expectedExitCode, output });
  fs.writeFileSync(evidencePath, JSON.stringify(record, null, 2) + '\n');
  console.log(output);
  process.exitCode = result.status === expectedExitCode ? 0 : 1;
}
if (mode === 'a-mutation') {
  const source = 'packages/contracts/src/index.ts';
  const original = fs.readFileSync(source);
  const aSource = git('show', record.dependencies.aFixed + ':' + source);
  const aLine = 'retryable: code === "CAPABILITY_UNAVAILABLE",';
  if (!aSource.includes(aLine) || !original.toString().includes('retryable: false,')) throw Error('FIXTURE_PRECONDITION');
  const mutated = Buffer.from(original.toString().replace('retryable: false,', aLine));
  record.mutation = { source, aLine, beforeSha256: sha(original), mutatedSha256: sha(mutated), onlyRetryableExpressionChanged: true };
  try {
    fs.writeFileSync(source, mutated);
    run(electron, ['node_modules/vitest/vitest.mjs', 'run', 'packages/contracts/src/checks.test.ts', ...(args.includes('--contract-only') ? [] : ['packages/infrastructure/src/wiki-store.test.ts']), '-t', 'A-W08'], 1);
  } finally {
    fs.writeFileSync(source, original);
    record.mutation.restoredSha256 = sha(fs.readFileSync(source));
    record.mutation.restored = record.mutation.restoredSha256 === record.mutation.beforeSha256;
    fs.writeFileSync(evidencePath, JSON.stringify(record, null, 2) + '\n');
  }
} else {
  const executable = mode === 'electron' ? electron : mode === 'pnpm' ? 'C:/Users/陈宇柠/AppData/Local/pnpm/global/v11/82859147b4fec5e788f016e5ca7f0a52c473a92cd2037e4c8bdc7029c86b60f3/node_modules/pnpm/pnpm.exe' : process.execPath;
  run(executable, args);
}
